const input = $input.first().json;
const text = (input.body && input.body.text) || input.text || '';
const targetRatio = (input.body && input.body.targetRatio) || input.targetRatio || 70;

const originalCharCount = text.length;
const originalTokenCount = Math.round(originalCharCount / 4);

function stripDividers(t) {
  return t.replace(/^[ \t]*[-=*_~]{3,}[ \t]*$/gm, '');
}

const FILLER_LINE_RE = [
  /^thanks( everyone| all| team)?\.?$/i,
  /^sounds good\.?$/i,
  /^let'?s revisit( next week)?\.?$/i,
  /^i'?ll schedule another meeting\.?$/i,
  /^great discussion\.?$/i,
  /^thank you\.?$/i,
];
function stripFillerLines(t) {
  return t.split('\n').filter(line => !FILLER_LINE_RE.some(re => re.test(line.trim()))).join('\n');
}

function looksLikeCode(s) {
  return /[{};]|=>|\bfunction\s|\bclass\s|\bstruct\s|\bfor\s*\(|\bwhile\s*\(|\bimport\s|\breturn\s/.test(s);
}

function compactListBlock(paragraph) {
  if (looksLikeCode(paragraph)) return paragraph;
  const lines = paragraph.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length < 3) return paragraph;
  const allShort = lines.every(l => l.length <= 60 && !/[.!?:]$/.test(l));
  if (!allShort) return paragraph;
  return lines.join(', ');
}

function preprocess(t) {
  let out = stripDividers(t);
  out = stripFillerLines(out);
  out = out.replace(/\n{3,}/g, '\n\n');
  out = out.split(/\n\s*\n/).map(compactListBlock).join('\n\n');
  return out;
}

const preprocessed = preprocess(text);

const MAX = 500;
const paragraphs = preprocessed.split(/\n\s*\n/);
const chunks = [];
let current = '';

// Break priority when a paragraph exceeds MAX: last sentence-ending punctuation within
// budget (best — never splits mid-sentence), else last newline, else last whitespace,
// else a hard cut at MAX as an absolute last resort (a single token longer than MAX chars).
function lastSentenceBreak(s, limit) {
  let best = -1;
  for (const mark of ['. ', '! ', '? ']) {
    const idx = s.lastIndexOf(mark, limit);
    if (idx > best) best = idx + 1; // break right after the punctuation mark
  }
  return best;
}

function flushOversized() {
  while (current.length > MAX) {
    let breakAt = lastSentenceBreak(current, MAX);
    if (breakAt <= 0) breakAt = current.lastIndexOf('\n', MAX);
    if (breakAt <= 0) breakAt = current.lastIndexOf(' ', MAX);
    if (breakAt <= 0) breakAt = MAX;
    chunks.push(current.slice(0, breakAt));
    current = current.slice(breakAt).replace(/^[\n ]+/, '');
  }
}

for (const para of paragraphs) {
  const candidate = current ? current + '\n\n' + para : para;
  if (candidate.length > MAX && current.length > 0) {
    chunks.push(current);
    current = para;
  } else {
    current = candidate;
  }
  flushOversized();
}
if (current.trim().length > 0) chunks.push(current);
if (chunks.length === 0) chunks.push(preprocessed);

return chunks.map((c, i) => ({
  json: {
    chunk: c,
    chunk_index: i,
    original_char_count: originalCharCount,
    original_token_count: originalTokenCount,
    original_text: text,
    target_ratio: targetRatio,
  },
}));

const items = $input.all();

const STOPWORDS = new Set(['the','a','an','and','or','but','of','to','in','on','for','with','is','are','was','were','be','been','being','this','that','these','those','it','as','at','by','from','has','have','had','will','would','could','should','can','may','might','not','no','so','if','then','than','also','into','about','over','under','more','most','some','such','only','very']);
const WORD_NUM = { zero:'0', one:'1', two:'2', three:'3', four:'4', five:'5', six:'6', seven:'7', eight:'8', nine:'9', ten:'10' };
const UNIT_NORM = { milliseconds:'ms', millisecond:'ms', ms:'ms', seconds:'s', second:'s' };

function normalizeToken(w) {
  const lw = w.toLowerCase();
  if (WORD_NUM[lw]) return WORD_NUM[lw];
  if (UNIT_NORM[lw]) return UNIT_NORM[lw];
  return lw;
}

function contentSignature(sent) {
  const words = (sent.match(/\b[\w.]+\b/g) || []).map(normalizeToken);
  return new Set(words.filter(w => !STOPWORDS.has(w) && w.length > 1));
}

function jaccard(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let inter = 0;
  for (const w of setA) if (setB.has(w)) inter++;
  return inter / (setA.size + setB.size - inter);
}

return items.map(item => {
  let text = item.json.cleaned_chunk || item.json.chunk || item.json.text || '';

  let sentences = text.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean);

  // Pass 1: near-literal dedup (existing) — catches repeated sentences with only
  // filler-phrase or punctuation differences.
  const seenCore = new Set();
  const pass1 = [];
  for (const sent of sentences) {
    const normalized = sent.toLowerCase().replace(/[.,!?;:]/g, '').replace(/\s+/g, ' ').trim();
    const core = normalized
      .replace(/^(and )?once again /,'')
      .replace(/^(as a matter of fact,?|it is important to note that,?|for all intents and purposes,?|needless to say,?|in order to actually|it goes without saying that,?|at this particular point in time,?|with all due respect and without any doubt whatsoever,?|the fact of the matter is that,?|truth be told,?)\s*/g, '')
      .trim();
    if (!seenCore.has(core)) {
      seenCore.add(core);
      pass1.push(sent);
    }
  }

  // Pass 2: semantic near-duplicate clustering via content-word Jaccard, with number/unit
  // normalization (two -> 2, milliseconds -> ms) so paraphrases of the same fact collapse
  // to one mention (e.g. "targets latency below two milliseconds" vs "has a latency
  // objective under 2 ms"). First occurrence in document order wins.
  const sigs = pass1.map(s => ({ text: s, sig: contentSignature(s) }));
  const kept = [];
  for (const cand of sigs) {
    const isDup = kept.some(k => jaccard(k.sig, cand.sig) >= 0.32);
    if (!isDup) kept.push(cand);
  }
  text = kept.map(k => k.text).join(' ');

  text = text.replace(/\n{3,}/g, '\n\n');

  return { json: { ...item.json, cleaned_chunk: text.trim() } };
});

