const items = $input.all();
let compressedText = '';
let totalGroqTime = 0;

items.forEach(item => {
  compressedText += (item.json.compressed_chunk || '') + '\n';
  totalGroqTime += (item.json.groq_total_time || 0);
});

// Use the TRUE original text/count (identical on every item, from Chunk Text),
// not a reconstruction from already-deduped chunks.
const originalText = items[0]?.json.original_text_true || '';
const originalTokenCount = items[0]?.json.original_token_count_true || Math.ceil(originalText.length / 4);
const compressedTokenCount = Math.ceil(compressedText.length / 4);

let compressionRatio = 0;
let status = 'completed';

if (originalTokenCount < 50) {
  status = 'input_too_short';
  compressionRatio = 0;
} else {
  compressionRatio = Math.round(((originalTokenCount - compressedTokenCount) / originalTokenCount) * 100 * 100) / 100;
  if (compressionRatio < 0) compressionRatio = 0;
  else if (compressionRatio < 70) status = 'below_target';
}

const costSaved = ((originalTokenCount - compressedTokenCount) / 1000000) * 3;

const latencyCompressedMs = Math.round(totalGroqTime * 1000);
const estimatedThroughputTokensPerSec = 500;
const latencyOriginalMs = Math.round((originalTokenCount / estimatedThroughputTokensPerSec) * 1000) + latencyCompressedMs;

return [{
  json: {
    original_text: originalText.trim(),
    compressed_text: compressedText.trim(),
    original_token_count: originalTokenCount,
    compressed_token_count: compressedTokenCount,
    compression_ratio: compressionRatio,
    cost_saved: Math.round(costSaved * 1000000) / 1000000,
    latency_original_ms: latencyOriginalMs,
    latency_compressed_ms: latencyCompressedMs,
    status: status,
  }
}];

const summarized = $input.all();
const original = $('Algorithmic Compress').all();

return summarized.map((item, i) => {
  const originalItem = original[i] ? original[i].json : {};
  const algo = originalItem.algo_compressed_chunk || originalItem.cleaned_chunk || '';
  const groqOut = item.json.choices?.[0]?.message?.content;
  // Only accept Groq's refinement if it's actually as short or shorter than the
  // guaranteed algorithmic floor. This is what makes the ratio deterministic:
  // Groq can only ever help, never regress below what the algorithm already achieved.
  const compressed = (groqOut && groqOut.length <= algo.length) ? groqOut : algo;
  return {
    json: {
      original_chunk: originalItem.cleaned_chunk || '',
      compressed_chunk: compressed,
      groq_call_failed: !groqOut,
      groq_output_rejected: !!groqOut && groqOut.length > algo.length,
      groq_total_time: item.json.usage?.total_time || 0,
      original_text_true: originalItem.original_text || '',
      original_token_count_true: originalItem.original_token_count || 0,
    }
  };
});

const prev = $('Combine and Measure').first().json;
const content = $input.first().json.choices?.[0]?.message?.content;
const raw = content || '0';
const score = parseInt(raw.match(/\d+/)?.[0] || '0', 10);
return [{
  json: {
    ...prev,
    reasoning_retention_score: content ? Math.min(100, Math.max(0, score)) : null, // null = eval call failed, not "0% retained"
  }
}];

