const STOPWORDS = new Set(['the','a','an','and','or','but','of','to','in','on','for','with','is','are','was','were','be','been','being','this','that','these','those','it','as','at','by','from','has','have','had','will','would','could','should','can','may','might','not','no','so','if','then','than','also','into','about','over','under','more','most','some','such','only','very']);

function tokenizeWords(s) {
  return s.match(/\b[\w'-]+\b/g) || [];
}

function scoreSentence(sent) {
  const words = tokenizeWords(sent);
  let score = 0;
  for (const w of words) {
    if (/\d/.test(w)) score += 2;
    else if (/^[A-Z][a-zA-Z]*$/.test(w) && w.length > 1) score += 1.5;
    else if (w.length > 6 && !STOPWORDS.has(w.toLowerCase())) score += 1;
    else if (STOPWORDS.has(w.toLowerCase())) score -= 0.2;
  }
  // Favor code-like fragments so they're likely kept when there's room, but
  // never unconditionally exempt them from the budget.
  if (/[{};]|=>|\bfunction\s|\bclass\s|\bstruct\s|\bfor\s*\(|\bwhile\s*\(|\breturn\s/.test(sent)) score += 3;
  // Label/definition-style fragments ("Purpose: ...", "Root cause: ...", "Issue: ...", "Fix: ...")
  // are reliably the fact-bearing sentences in structured documents and were being under-weighted
  // relative to fact-dense-but-less-critical fragments (e.g. name lists), which cost real Q&A
  // answerability in testing even while the overall density score looked fine.
  if (/:\s/.test(sent)) score += 2;
  const denom = Math.sqrt(Math.max(words.length, 1));
  return score / denom;
}

function algorithmicCompress(text, targetRatio) {
  const totalTokens = Math.ceil(text.length / 4) || 1;
  // No budget slack — the ratio requirement is a hard floor and a 20% slack test already
  // landed a real run at 69.57% (under it). Retention gains here come from the chunking and
  // scoring fixes instead (sentence-safe chunk breaks, colon-label boost, digit-split fix),
  // which don't trade against the ratio guarantee.
  const targetTokens = Math.max(1, Math.round(totalTokens * (1 - targetRatio / 100)));

  // Negative lookbehind excludes splitting right after a bare list-number like "1." —
  // otherwise "1." becomes its own fragment, scores deceptively well from the digit bonus
  // (cheap + scores well) and crowds out the actual question/list text that followed it.
  // Also split on bare newlines regardless of punctuation: dense code (JSX attributes,
  // markup) can run hundreds of characters with no '.', '!', '?', or ';' at all, which
  // otherwise turns an entire chunk into one unsplittable, unbudgeted fragment that the
  // "never keep nothing" fallback then forces through whole, blowing the budget for that
  // chunk 2-3x over. Newline is the natural fragment boundary for code.
  const parts = text.split(/(?<=[^\d][.!?;])\s+|\n+/).map(s => s.trim()).filter(Boolean);
  const fragments = parts.map((s, i) => ({
    order: i,
    text: s,
    tokens: Math.ceil(s.length / 4) || 1,
    score: scoreSentence(s),
  }));

  const bySelection = [...fragments].sort((a, b) => b.score - a.score);
  const keepSet = new Set();
  let used = 0;
  for (const f of bySelection) {
    if (used >= targetTokens) break;
    if (used + f.tokens <= targetTokens || keepSet.size === 0) {
      keepSet.add(f);
      used += f.tokens;
    }
  }

  const kept = fragments.filter(f => keepSet.has(f)).sort((a, b) => a.order - b.order);
  return kept.map(f => f.text).join(' ');
}

const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    algo_compressed_chunk: algorithmicCompress(item.json.cleaned_chunk || '', item.json.target_ratio || 70),
  },
}));
